import re
import sys
from pathlib import Path

REPLACEMENTS = [
    ("FRIDA", "PENGU"),
    ("Frida", "Pengu"),
    ("frida", "pengu"),
]

# These exact identifiers are generated by frida-core's top-level meson.build
# (cdata.set(...) / --define=...) and therefore live outside the source tree
# this script rewrites. Any Vala/C reference to them (Config.FRIDA_LIBDIR,
# #if HAVE_FRIDA_GLIB, etc.) must keep matching the meson-generated name
# exactly, so they're protected from the general substitution below.
PROTECTED_TOKENS = [
    "FRIDA_VERSION",
    "FRIDA_MAJOR_VERSION",
    "FRIDA_MINOR_VERSION",
    "FRIDA_MICRO_VERSION",
    "FRIDA_NANO_VERSION",
    "FRIDA_PREFIX",
    "FRIDA_LIBDIR_NAME",
    "FRIDA_LIBDIR",
    "FRIDA_HELPER_NAME",
    "FRIDA_AGENT_NAME",
    "FRIDA_COMPILER_BACKEND_NAME",
    "HAVE_FRIDA_GLIB",
    # Static headers referenced by their literal on-disk filename from
    # meson.build (files(...)) and/or .vapi (cheader_filename = "..."):
    # this script doesn't rename filenames, only file content, so any
    # #include/cheader_filename spelling of these must stay unchanged
    # too or the compiler can't find the (still frida-*-named) file.
    "frida-atomics.h",
    "frida-darwin.h",
    "frida-jni.h",
    "frida-linux-bpf.h",
    "frida-linux-perf-event.h",
    "frida-tvos.h",
    "frida-selinux.h",
    "frida-helper-service-glue.h",
    "frida-helper-process-glue.h",
    # These are also static filenames from this script's point of view,
    # but they're generated BY the build itself (meson's vala_header /
    # vala_vapi params in lib/*/meson.build and src/meson.build) rather
    # than checked into the repo - same reasoning applies: the actual
    # generated filename is whatever meson.build says (untouched), so
    # any #include of it elsewhere must keep matching that exact name.
    "frida-base-1.0.vapi",
    "frida-payload-1.0.vapi",
    "frida-base.h",
    "frida-agent.h",
    "frida-gadget.h",
    "frida-payload.h",
    "frida-pipe.h",
    "frida-core.h",
    "frida-core.vapi",
    # static_library()/executable() targets that don't pass an explicit
    # vala_header: still get one, meson just derives its name from the
    # target name itself (e.g. static_library('frida-helper-backend', ...)
    # -> frida-helper-backend.h). frida-helper-backend.h caused the same
    # "file not found" failure as the explicit ones above; frida-netif.h
    # and frida-tests.h follow the identical pattern so are protected
    # pre-emptively.
    "frida-helper-backend.h",
    "frida-netif.h",
    "frida-tests.h",
]
# Longest-first so e.g. FRIDA_LIBDIR_NAME is protected whole rather than
# leaving a dangling _NAME after FRIDA_LIBDIR matches first.
PROTECTED_TOKENS.sort(key=len, reverse=True)
_PLACEHOLDER_FMT = "\x00PROTECTED_TOKEN_{}\x00"


def protect_and_replace(text: str) -> str:
    saved = []

    def stash(match: re.Match) -> str:
        saved.append(match.group(0))
        return _PLACEHOLDER_FMT.format(len(saved) - 1)

    protect_re = re.compile("|".join(re.escape(t) for t in PROTECTED_TOKENS))
    text = protect_re.sub(stash, text)

    for old, new in REPLACEMENTS:
        text = text.replace(old, new)

    for i, original in enumerate(saved):
        text = text.replace(_PLACEHOLDER_FMT.format(i), original)

    return text


# Of the 6 excluded files, only frida-linux.vapi, frida-atomics.vapi and
# libc-shim.vapi live under the `Frida` namespace tree (darwin-gcd.vapi and
# darwin-xpc.vapi declare their own unrelated `namespace Darwin.*`, and
# jni.vapi uses bare `namespace JNI`) - only those three have members at
# risk of an unqualified reference elsewhere breaking once that reference's
# own file is renamed out of namespace Frida:
#   - frida-linux.vapi declares its 11 members directly under `Frida`
#     (dlopen/MAP_ANONYMOUS/BpfRingbufFlags/PerfEventAttr/...)
#   - frida-atomics.vapi nests them under the sub-namespace `Frida.Atomics`
#   - libc-shim.vapi nests them under the sub-namespace `Frida.LibcShim`
# Either way, a bare mention of the member name (frida-linux.vapi) or of
# the sub-namespace name itself (Atomics./LibcShim.) needs "Frida." (or
# "Frida.Atomics."/"Frida.LibcShim.") prepended once its own file no longer
# sits inside `namespace Frida`.
#
# A blanket `using Frida;` in every renamed .vala file was tried and
# reverted: it breaks any compilation unit that doesn't itself pull in
# frida-linux.vapi (e.g. tools/resource-compiler.vala), since Vala's
# `using` directive requires the named namespace to actually resolve to
# something in that unit's own dependency graph. Qualifying only the
# specific bare references that exist is more code but doesn't have that
# failure mode - a file that never mentions PerfEventAttr etc. is left
# completely alone.
#
# dlopen/dlclose/dlsym/dlerror/MAP_ANONYMOUS were initially left out on
# the theory that they're common enough names that blindly qualifying
# every bare mention risks redirecting some unrelated reference onto this
# specific binding. In practice src/linux/frida-helper-backend.vala and
# proc-mem-injector.vala do call them bare, and nothing else in the tree
# provides a competing implicit binding, so the exclusion just broke the
# Android build ("The name `dlopen' does not exist in the context of
# `Pengu.InjectSession.bootstrap'") - moved them into the qualified list
# alongside the rest of frida-linux.vapi's members.
_EXCLUDED_VAPI_BARE_SYMBOLS = [
    # lib/base/frida-linux.vapi (direct members of `namespace Frida`)
    "BpfRingbufFlags",
    "BPF_RINGBUF_HEADER_SIZE",
    "PERF_EVENT_TYPE_SOFTWARE",
    "PERF_EVENT_COUNT_SW_CPU_CLOCK",
    "PerfEventAttr",
    "PerfEventType",
    "dlopen",
    "dlclose",
    "dlsym",
    "dlerror",
    "MAP_ANONYMOUS",
    # lib/base/frida-atomics.vapi (`namespace Frida.Atomics`) - the
    # sub-namespace name itself is the bare identifier at risk, e.g.
    # `Atomics.load_u64_acquire(...)` used inside lib/base/linux.vala.
    "Atomics",
    # lib/payload/libc-shim.vapi (`namespace Frida.LibcShim`) - same
    # pattern as Atomics above.
    "LibcShim",
]
# src/linux/frida-helper-backend.vala's HelperLibcApi struct has fields
# literally named `dlopen`/`dlclose`/`dlsym`/`dlerror` (holding resolved
# function-pointer addresses, mirroring the real libc functions by name).
# A field DECLARATION site (`void * dlopen;`) is textually indistinguishable
# from a bare word-boundary match, but qualifying it produces `void *
# Frida.dlopen;`, which isn't a legal field name and breaks parsing so
# badly the rest of the class reads as garbage ("inner `enum' types are
# not supported in `HelperLibcApi'", cascading for 20+ lines). Every
# legitimate bare USAGE of these symbols in the tree is followed by `,`,
# `)`, or another operator/token before any `;` ever appears - only the
# field declarations have the symbol immediately (whitespace only)
# followed by `;` - so excluding that one shape disambiguates them without
# needing a real parser.
_BARE_SYMBOL_RE = re.compile(
    r"(?<![.\w])(" + "|".join(_EXCLUDED_VAPI_BARE_SYMBOLS) + r")\b(?!\s*;)"
)


def qualify_bare_excluded_vapi_symbols(text: str) -> str:
    return _BARE_SYMBOL_RE.sub(lambda m: "Frida." + m.group(1), text)


# Only real source files get text-substituted. meson.build / meson_options.txt /
# .wrap files are deliberately excluded: they reference subproject and
# dependency names (e.g. subproject('frida-gum'), dependency('frida-gum-1.0'))
# that must keep matching the actual on-disk directory names, which this
# script does NOT rename. Renaming those identifiers without also renaming
# directories would break meson's subproject resolution.
#
# .version/.symbols/.def files ARE included: they're linker version-scripts
# and export lists (e.g. lib/agent/frida-agent-android.version lists
# "frida_agent_main" as the sole global export) that must name the exact C
# symbol the corresponding Vala source now compiles to after renaming. Every
# such file in frida-core was checked by hand and contains only
# frida-prefixed symbol names/wildcards or comments - no filename or
# subproject coupling - so blanket content substitution is safe here.
#
# .resources files ARE included too: they're resource-compiler manifests
# (e.g. src/icons.resources: "[resource-compiler]\nnamespace = Frida.Data.Icons")
# whose namespace= line must match whatever the actual .vala source now
# refers to (Frida.Data.Icons -> Pengu.Data.Icons) after renaming - same
# reasoning as the linker files above, and every such file was checked by
# hand to contain only that one namespace= line, no path/subproject coupling.
SOURCE_SUFFIXES = {
    ".vala", ".vapi", ".c", ".h", ".cpp", ".cc", ".hpp", ".m", ".mm", ".java",
    ".version", ".symbols", ".def", ".resources",
}
EXTRA_EXACT_NAMES = {"Makefile"}

EXCLUDE_DIR_NAMES = {".git", "releng", "deps", "build", "toolchain"}


# Thin .vapi bindings straight onto static, un-renamed headers
# (frida-linux-bpf.h, frida-atomics.h, frida-darwin.h, frida-jni.h, ...).
# Most of their consts/enums have no explicit cname/cprefix, so Vala
# derives the expected C symbol name from the enclosing `namespace Frida`
# by convention - renaming that namespace would silently break every
# such implicit binding (e.g. BPF_RINGBUF_HEADER_SIZE would start
# looking for PENGU_BPF_RINGBUF_HEADER_SIZE, which doesn't exist).
# These files are pure C interop plumbing with no runtime-visible
# strings of their own, so excluding them entirely is both safe and low
# value to rename in the first place.
#
# Their backing C headers need the same exclusion, for the same reason -
# frida-linux.vapi/frida-atomics.vapi/darwin-gcd.vapi/darwin-xpc.vapi bind
# to C symbols in these headers using implicit Vala naming (a cprefix, or
# no cname at all), so the header's typedef/enum/#define/function names
# must keep matching the vapi's un-renamed "Frida" namespace exactly. This
# bit both ways in practice: PerfEventAttr's cname is derived from `Frida`
# by frida-linux.vapi and expected as "FridaPerfEventAttr", but
# frida-linux-perf-event.h (not excluded before this fix) got its own
# typedef renamed to "PenguPerfEventAttr" - a straight content mismatch,
# same failure mode as the meson.build literals above, just one layer
# removed (a static header instead of a build-system literal). Not every
# static header needs this: frida-jni.h/frida-tvos.h contain no
# Frida-prefixed C symbols (only an include guard, harmless either way),
# and frida-selinux.h/frida-helper-*-glue.h back NON-excluded vala files
# that get renamed in lockstep with them, so only headers backing an
# EXCLUDED vapi's implicit-naming members are listed here.
EXCLUDE_RELATIVE_FILES = {
    "lib/base/frida-linux.vapi",
    "lib/base/frida-atomics.vapi",
    "vapi/darwin-gcd.vapi",
    "vapi/darwin-xpc.vapi",
    "vapi/jni.vapi",
    "lib/payload/libc-shim.vapi",
    "lib/base/frida-atomics.h",
    "lib/base/frida-darwin.h",
    "lib/base/frida-linux-bpf.h",
    "lib/base/frida-linux-perf-event.h",
}


def should_process(path: Path, core_root: Path) -> bool:
    if any(part in EXCLUDE_DIR_NAMES for part in path.parts):
        return False
    try:
        rel = path.relative_to(core_root).as_posix()
    except ValueError:
        rel = path.as_posix()
    if rel in EXCLUDE_RELATIVE_FILES:
        return False
    if path.suffix in SOURCE_SUFFIXES:
        return True
    if path.name in EXTRA_EXACT_NAMES:
        return True
    return False


def rename_java_package_dir(core_root: Path):
    old_dir = core_root / "src" / "android-helper" / "re" / "frida"
    new_dir = core_root / "src" / "android-helper" / "re" / "pengu"
    if old_dir.is_dir():
        new_dir.parent.mkdir(parents=True, exist_ok=True)
        old_dir.rename(new_dir)
        print(f"[*] moved {old_dir} -> {new_dir}")
    else:
        print(f"[*] no android-helper java package dir at {old_dir}, skipping move")


# A handful of files are excluded from the general substitution (meson.build,
# to avoid breaking subproject()/dependency() name resolution; src/api/
# generate.py, because it hardcodes the "Frida" brand so pervasively - output
# filenames meson.build's own custom_target() expects verbatim, an input
# filename ("frida.vala") it reads directly, C-name reconstruction assuming
# every type is literally "Frida" + name, GIR/vapi namespace text, etc - that
# blanket substitution would create as many new mismatches as it fixed. But
# each still hardcodes a handful of literal C symbol/identifier names that
# DO need to track the frida->pengu rename applied everywhere else, so those
# specific literals are patched directly instead:
#   - lib/agent/meson.build's darwin -Wl,-exported_symbol,... link flag and
#     lib/agent+lib/gadget/meson.build's --move constructor/destructor
#     operations passed to modulate.py must match the literal C function
#     names in lib/agent/agent-glue.c and lib/gadget/gadget-glue.c (already
#     renamed normally, being plain .c files):
#       frida_agent_main:       namespace Frida.Agent { public void main }
#       frida_libc_shim_init/deinit, frida_on_load/frida_on_unload
#   - src/api/generate.py's parse_api() does
#     `re.search(r"...frida_{}...".format(f.name), all_headers)` to find
#     each public Vala function's C prototype inside the (renamed)
#     frida-core.h/frida-base.h text it's given, then unconditionally calls
#     `.group(0)` on the result. Since the header now says "pengu_<name>",
#     the hardcoded "frida_" makes the search always fail, crashing with
#     "AttributeError: 'NoneType' object has no attribute 'group'" instead
#     of quietly producing a wrong prototype the way finditer()-based scans
#     elsewhere in the same file do. This is the only crash-causing spot
#     found so far; everything else in generate.py builds a devkit
#     (frida-core.h/-1.0.vapi/Frida-1.0.gir under src/api/) that nothing in
#     this build actually reads (tools/package-server-fruity-pengrida.sh
#     only takes usr/bin/frida-server and usr/lib/frida-1.0/frida-agent.dylib
#     from the install DESTDIR), so a devkit that's internally
#     inconsistent about "Frida" vs "Pengu" naming but doesn't crash is an
#     acceptable outcome, not something worth chasing further.
# This is inherently a whack-a-mole list: any future frida-core change that
# hardcodes a new C symbol/identifier name this way needs a new entry here,
# the same way a new implicit Vala namespace-derived symbol needs a new
# PROTECTED_TOKENS/qualify entry above.
_LITERAL_PATCHES = [
    ("lib/agent/meson.build", [
        ("_frida_agent_main", "_pengu_agent_main"),
        ("'frida_libc_shim_init'", "'pengu_libc_shim_init'"),
        ("'frida_libc_shim_deinit'", "'pengu_libc_shim_deinit'"),
    ]),
    ("lib/gadget/meson.build", [
        ("'frida_libc_shim_init'", "'pengu_libc_shim_init'"),
        ("'frida_libc_shim_deinit'", "'pengu_libc_shim_deinit'"),
        ("'frida_on_load'", "'pengu_on_load'"),
        ("'frida_on_unload'", "'pengu_on_unload'"),
    ]),
    ("src/api/generate.py", [
        (' frida_{}.+?;".format(f.name)', ' pengu_{}.+?;".format(f.name)'),
    ]),
]


def patch_known_literals(core_root: Path):
    for relative, replacements in _LITERAL_PATCHES:
        path = core_root / relative
        if not path.is_file():
            print(f"[*] no {relative}, skipping literal-symbol patch")
            continue
        text = path.read_text(encoding="utf-8")
        new_text = text
        for old, new in replacements:
            if old not in new_text:
                print(f"[*] {relative}: '{old}' not found, skipping")
                continue
            new_text = new_text.replace(old, new)
            print(f"[*] {relative}: {old} -> {new}")
        if new_text != text:
            path.write_text(new_text, encoding="utf-8")


def rename_text_in_tree(root: Path) -> int:
    total = 0
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        if not should_process(path, root):
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except (UnicodeDecodeError, OSError):
            continue
        new_text = protect_and_replace(text)
        if path.suffix == ".vala":
            new_text = qualify_bare_excluded_vapi_symbols(new_text)
        if new_text != text:
            path.write_text(new_text, encoding="utf-8")
            n = sum(text.count(old) for old, _ in REPLACEMENTS)
            total += n
            print(f"[*] {path}: {n} replacement(s)")
    return total


def main(argv):
    if len(argv) != 2:
        print(f"Usage: {argv[0]} <frida-core-dir>", file=sys.stderr)
        return 2

    core_root = Path(argv[1])
    if not core_root.is_dir():
        print(f"{core_root}: not a directory", file=sys.stderr)
        return 1

    rename_java_package_dir(core_root)
    patch_known_literals(core_root)
    total = rename_text_in_tree(core_root)
    print(f"[*] total replacements: {total}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
